{
  "additionalProperties": false,
  "properties": {
    "comps": {
      "items": {
        "type": "object"
      },
      "maxItems": 20,
      "type": "array"
    },
    "snapshot": {
      "description": "Raw market and fundamentals data keyed by data type",
      "type": "object"
    },
    "target": {
      "maxLength": 64,
      "pattern": "^[A-Za-z0-9._-]+$",
      "type": "string"
    }
  },
  "required": [
    "target",
    "snapshot"
  ],
  "type": "object"
}

